// src/pages/CreatePostPage.jsx
import React, { useState, useRef, useEffect } from 'react';
import './CreatePostPage.css';
import { MapContainer, TileLayer, Marker, Popup } from 'react-leaflet';
import 'leaflet/dist/leaflet.css'; // Important for map styles
import L from 'leaflet';
import { useCallback } from 'react';


const CreatePostPage = () => {
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [division, setDivision] = useState('');
  const [district, setDistrict] = useState('');
  const [upazila, setUpazila] = useState('');
  const [union, setUnion] = useState('');
  const [file, setFile] = useState(null);
  const [preview, setPreview] = useState('');
  const [platforms, setPlatforms] = useState({
    facebook: false, instagram: false, telegram: false,
    tiktok: false, whatsapp: false, youtube: false, sms: false
  });
  const [checkCompliance, setCheckCompliance] = useState(false);

  const mapRef = useRef();
  
  const redPinIcon = L.icon({
  iconUrl: 'https://raw.githubusercontent.com/pointhi/leaflet-color-markers/master/img/marker-icon-red.png',
  shadowUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/images/marker-shadow.png',
  iconSize: [25, 41],
  iconAnchor: [12, 41],
  popupAnchor: [1, -34],
  shadowSize: [41, 41]
});

  // Location hierarchy
  const locationData = {
    Dhaka: {
      districts: {
        Dhaka: { upazilas: { Dhanmondi: ['Ward 47', 'Ward 48'], Gulshan: ['Banani', 'Gulshan-1'], Mirpur: ['Mirpur-10'], Uttara: ['Sector-7'] } },
        Gazipur: { upazilas: { Kaliakoir: ['Chandra'], Sreepur: ['Barmi'] } }
      }
    },
    Chattogram: {
      districts: {
        Chattogram: { upazilas: { Kotwali: ['Anderkilla'], Panchlaish: ['Khulshi'], 'Double Mooring': ['Agrabad'] } },
        "Cox’s Bazar": { upazilas: { 'Cox’s Bazar Sadar': ['Jhilongja'], Ukhiya: ['Raja Palong'] } }
      }
    },
    Rajshahi: { districts: { Rajshahi: { upazilas: { Boalia: ['Boalia'], Matihar: ['Matihar'] } } } },
    Khulna: { districts: { Khulna: { upazilas: { Sonadanga: ['Sonadanga'], 'Khulna Sadar': ['Atra Gilatala'] } } } },
    Sylhet: { districts: { Sylhet: { upazilas: { 'Sylhet Sadar': ['Tultikar'], 'Dakshin Surma': ['Moglabazar'] } } } }
  };

  // Coordinates for zooming (real lat/lon)
  const coordinates = {
    '': { lat: 23.6850, lon: 90.3563, zoom: 7 }, // Bangladesh full map
    'Dhaka': { lat: 23.8103, lon: 90.4125, zoom: 8 },
    'Dhaka_Dhaka': { lat: 23.8103, lon: 90.4125, zoom: 10 },
    'Dhaka_Dhaka_Dhanmondi': { lat: 23.7461, lon: 90.3760, zoom: 13 },
    'Dhaka_Dhaka_Dhanmondi_Ward 47': { lat: 23.7461, lon: 90.3760, zoom: 15 },
    'Dhaka_Dhaka_Dhanmondi_Ward 48': { lat: 23.7461, lon: 90.3760, zoom: 15 },
    'Dhaka_Dhaka_Gulshan': { lat: 23.7925, lon: 90.4155, zoom: 13 },
    'Dhaka_Dhaka_Gulshan_Banani': { lat: 23.7938, lon: 90.4053, zoom: 15 },
    'Dhaka_Dhaka_Gulshan_Gulshan-1': { lat: 23.7925, lon: 90.4155, zoom: 15 },
    'Dhaka_Dhaka_Mirpur': { lat: 23.8093, lon: 90.3609, zoom: 13 },
    'Dhaka_Dhaka_Mirpur_Mirpur-10': { lat: 23.8069, lon: 90.3681, zoom: 15 },
    'Dhaka_Dhaka_Uttara': { lat: 23.8769, lon: 90.4026, zoom: 13 },
    'Dhaka_Dhaka_Uttara_Sector-7': { lat: 23.8678, lon: 90.3969, zoom: 15 },
    'Dhaka_Gazipur': { lat: 24.0023, lon: 90.4267, zoom: 10 },
    'Dhaka_Gazipur_Kaliakoir': { lat: 24.0750, lon: 90.2167, zoom: 12 },
    'Dhaka_Gazipur_Kaliakoir_Chandra': { lat: 24.0667, lon: 90.2167, zoom: 14 },
    'Dhaka_Gazipur_Sreepur': { lat: 24.1991, lon: 90.4843, zoom: 12 },
    'Dhaka_Gazipur_Sreepur_Barmi': { lat: 24.1333, lon: 90.4833, zoom: 14 },
    'Chattogram': { lat: 22.3569, lon: 91.7832, zoom: 8 },
    'Chattogram_Chattogram': { lat: 22.3569, lon: 91.7832, zoom: 10 },
    'Chattogram_Chattogram_Kotwali': { lat: 22.3384, lon: 91.8320, zoom: 13 },
    'Chattogram_Chattogram_Kotwali_Anderkilla': { lat: 22.3400, lon: 91.8333, zoom: 15 },
    'Chattogram_Chattogram_Panchlaish': { lat: 22.3625, lon: 91.8256, zoom: 13 },
    'Chattogram_Chattogram_Panchlaish_Khulshi': { lat: 22.3625, lon: 91.8256, zoom: 15 },
    'Chattogram_Chattogram_Double Mooring': { lat: 22.3167, lon: 91.8000, zoom: 13 },
    'Chattogram_Chattogram_Double Mooring_Agrabad': { lat: 22.3250, lon: 91.8125, zoom: 15 },
    'Chattogram_Cox’s Bazar': { lat: 21.4272, lon: 92.0058, zoom: 10 },
    'Chattogram_Cox’s Bazar_Cox’s Bazar Sadar': { lat: 21.4272, lon: 92.0058, zoom: 12 },
    'Chattogram_Cox’s Bazar_Cox’s Bazar Sadar_Jhilongja': { lat: 21.4272, lon: 92.0058, zoom: 14 },
    'Chattogram_Cox’s Bazar_Ukhiya': { lat: 21.2125, lon: 92.1000, zoom: 12 },
    'Chattogram_Cox’s Bazar_Ukhiya_Raja Palong': { lat: 21.2125, lon: 92.1000, zoom: 14 },
    'Rajshahi': { lat: 24.3745, lon: 88.6042, zoom: 8 },
    'Rajshahi_Rajshahi': { lat: 24.3745, lon: 88.6042, zoom: 10 },
    'Rajshahi_Rajshahi_Boalia': { lat: 24.3667, lon: 88.6000, zoom: 13 },
    'Rajshahi_Rajshahi_Boalia_Boalia': { lat: 24.3667, lon: 88.6000, zoom: 15 },
    'Rajshahi_Rajshahi_Matihar': { lat: 24.3833, lon: 88.6167, zoom: 13 },
    'Rajshahi_Rajshahi_Matihar_Matihar': { lat: 24.3833, lon: 88.6167, zoom: 15 },
    'Khulna': { lat: 22.8456, lon: 89.5403, zoom: 8 },
    'Khulna_Khulna': { lat: 22.8456, lon: 89.5403, zoom: 10 },
    'Khulna_Khulna_Sonadanga': { lat: 22.8167, lon: 89.5500, zoom: 13 },
    'Khulna_Khulna_Sonadanga_Sonadanga': { lat: 22.8167, lon: 89.5500, zoom: 15 },
    'Khulna_Khulna_Khulna Sadar': { lat: 22.8167, lon: 89.5500, zoom: 13 },
    'Khulna_Khulna_Khulna Sadar_Atra Gilatala': { lat: 22.8167, lon: 89.5500, zoom: 15 },
    'Sylhet': { lat: 24.8949, lon: 91.8687, zoom: 8 },
    'Sylhet_Sylhet': { lat: 24.8949, lon: 91.8687, zoom: 10 },
    'Sylhet_Sylhet_Sylhet Sadar': { lat: 24.9000, lon: 91.8833, zoom: 13 },
    'Sylhet_Sylhet_Sylhet Sadar_Tultikar': { lat: 24.9000, lon: 91.8833, zoom: 15 },
    'Sylhet_Sylhet_Dakshin Surma': { lat: 24.8500, lon: 91.8833, zoom: 13 },
    'Sylhet_Sylhet_Dakshin Surma_Moglabazar': { lat: 24.8500, lon: 91.8833, zoom: 15 },
  };

const getLocationKey = useCallback(() => {
  let key = '';
  if (division) key += division;
  if (district) key += '_' + district;
  if (upazila) key += '_' + upazila;
  if (union) key += '_' + union;
  return key;
}, [division, district, upazila, union]);


useEffect(() => {
  if (mapRef.current) {
    const location = coordinates[getLocationKey()] || coordinates[''];
    mapRef.current.flyTo([location.lat, location.lon], location.zoom, { duration: 1.5 });
  }
}, [getLocationKey]);


  const handleFileDrop = (e) => {
    e.preventDefault();
    const file = e.dataTransfer.files[0];
    if (file && file.size <= 50 * 1024 * 1024) {
      setFile(file);
      setPreview(URL.createObjectURL(file));
    }
  };

  const handleFileSelect = (e) => {
    const file = e.target.files[0];
    if (file && file.size <= 50 * 1024 * 1024) {
      setFile(file);
      setPreview(URL.createObjectURL(file));
    }
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    alert('Post submitted successfully!');
    console.log({ title, content, location: { division, district, upazila, union }, file: file?.name, platforms });
  };

  return (
    <div className="create-post-container">
      <div className="create-post-card">
        <h2>Create a New Post</h2>

        <div className="form-group">
          <label>Title</label>
          <input type="text" placeholder="Enter a catchy title" value={title} onChange={e => setTitle(e.target.value)} />
        </div>

        <div className="form-group">
          <label>Content</label>
          <textarea rows="7" placeholder="What's on your mind?" value={content} onChange={e => setContent(e.target.value)} />
        </div>

        <div className="location-section">
          <h3>Location</h3>
          <div className="location-grid">
            <select value={division} onChange={e => { setDivision(e.target.value); setDistrict(''); setUpazila(''); setUnion(''); }}>
              <option>Select Division</option>
              {Object.keys(locationData).map(d => <option key={d}>{d}</option>)}
            </select>

            <select value={district} onChange={e => { setDistrict(e.target.value); setUpazila(''); setUnion(''); }} disabled={!division}>
              <option>Select District</option>
              {division && Object.keys(locationData[division].districts).map(d => <option key={d}>{d}</option>)}
            </select>

            <select value={upazila} onChange={e => { setUpazila(e.target.value); setUnion(''); }} disabled={!district}>
              <option>Select Upazila</option>
              {district && Object.keys(locationData[division].districts[district].upazilas).map(u => <option key={u}>{u}</option>)}
            </select>

            <select value={union} onChange={e => setUnion(e.target.value)} disabled={!upazila}>
              <option>Select Union</option>
              {upazila && locationData[division].districts[district].upazilas[upazila].map(u => <option key={u}>{u}</option>)}
            </select>
          </div>

          <div className="map-container">
            <MapContainer
              center={[23.6850, 90.3563]} 
              zoom={7} 
              style={{ height: '400px', width: '100%' }}
              ref={mapRef}
            >
              <TileLayer
                url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
                attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
              />

		{union && (
		  <Marker 
		    position={[coordinates[getLocationKey()].lat, coordinates[getLocationKey()].lon]} 
		    icon={redPinIcon}
		  >
		    <Popup>
		      <strong>{union}</strong><br />
		      {upazila}, {district}, {division}
		    </Popup>
		  </Marker>
		)}

            </MapContainer>
          </div>
        </div>

        {/* Media, platforms, compliance, submit stay the same */}
        <div className="media-section">
          <h3>Media (Image/Video)</h3>
          <div className="drop-zone" onDrop={handleFileDrop} onDragOver={e => e.preventDefault()} onClick={() => document.getElementById('file-input').click()}>
            {preview ? <img src={preview} alt="Preview" className="media-preview" /> : (
              <>
                <p>Click to upload or drag and drop</p>
                <p>PNG, JPG or MP4 (MAX. 50MB)</p>
              </>
            )}
            <input id="file-input" type="file" accept="image/*,video/*" onChange={handleFileSelect} hidden />
          </div>
        </div>

        <div className="publish-section">
          <h3>Publish to</h3>
          <p>Select the social media platforms where you want to share this post.</p>
          <div className="platforms-grid">
            {Object.entries(platforms).map(([key, value]) => (
              <label key={key}>
                <input type="checkbox" checked={value} onChange={e => setPlatforms({ ...platforms, [key]: e.target.checked })} />
                <span>{key.charAt(0).toUpperCase() + key.slice(1)}</span>
              </label>
            ))}
          </div>
        </div>

        <label className="compliance-checkbox">
          <input type="checkbox" checked={checkCompliance} onChange={e => setCheckCompliance(e.target.checked)} />
          Check Compliance
        </label>

        <button className="submit-btn" onClick={handleSubmit}>Submit Post</button>
      </div>
    </div>
  );
};

export default CreatePostPage;
