import React from 'react';
import { NavLink } from 'react-router-dom';
import Drawer from '@mui/material/Drawer';
import IconButton from '@mui/material/IconButton';
import MenuIcon from '@mui/icons-material/Menu';
import Avatar from '@mui/material/Avatar';

const Sidebar = ({ open, onClose }) => {
  const menuItems = [
    { to: "/", label: "Home" },
    { to: "/create-post", label: "Create Post" },
    { to: "/candidates", label: "Candidates" },
    { to: "/ads", label: "Ads" },
    { to: "/analytics", label: "Analytics" },
    { to: "/transparency", label: "Transparency" },
  ];

  return (
    <Drawer variant="persistent" anchor="left" open={open} className="sidebar-drawer">
      <div className="sidebar">
        <div className="sidebar-header">
          <div className="logo">Citizen Connect</div>
          <IconButton onClick={onClose}>
            <MenuIcon />
          </IconButton>
        </div>

        <div className="menu-items">
          {menuItems.map((item) => (
            <NavLink
              key={item.to}
              to={item.to}
              className={({ isActive }) => `menu-item ${isActive ? 'active' : ''}`}
              end
            >
              {item.label}
            </NavLink>
          ))}
          <div className="menu-divider" />
          <NavLink to="/help" className={({ isActive }) => `menu-item ${isActive ? 'active' : ''}`}>
            Help
          </NavLink>
          <NavLink to="/admin" className={({ isActive }) => `menu-item ${isActive ? 'active' : ''}`}>
            Admin
          </NavLink>
        </div>

        <div className="sidebar-footer">
          <Avatar>N</Avatar>
          <div>
            <div className="user-name">Current User</div>
            <div className="user-email">user@example.com</div>
          </div>
        </div>
      </div>
    </Drawer>
  );
};

export default Sidebar;
